package ae.arch;

import java.util.Arrays;
import java.util.Objects;

/**
 * A file or directory member. A name ending in {@code /} is a directory and has no data.
 * The data array is copied on the way in and on the way out.
 */
public record ArchiveEntry(String name, byte[] data) {
    public ArchiveEntry {
        Names.validate(name);
        Objects.requireNonNull(data, "data");
        if (name.endsWith("/") && data.length > 0) {
            throw new IllegalArgumentException("directory with data: " + name);
        }
        data = data.clone();
    }

    public boolean directory() {
        return name.endsWith("/");
    }

    @Override
    public byte[] data() {
        return data.clone();
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof ArchiveEntry e && name.equals(e.name) && Arrays.equals(data, e.data);
    }

    @Override
    public int hashCode() {
        return 31 * name.hashCode() + Arrays.hashCode(data);
    }

    @Override
    public String toString() {
        return "ArchiveEntry[" + name + ", " + data.length + " bytes]";
    }
}

package ae.arch;

/** A malformed, unsafe or unrepresentable archive or file tree. */
public final class ArchiveException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public ArchiveException(String message) {
        super(message);
    }

    public ArchiveException(String message, Throwable cause) {
        super(message, cause);
    }
}

package ae.arch;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

/** Tree-level checks and file-system helpers shared by the formats. */
public final class Archives {
    private Archives() {}

    private static String stripSlash(String name) {
        return name.endsWith("/") ? name.substring(0, name.length() - 1) : name;
    }

    /** Rejects duplicate members ({@code a} and {@code a/} collide) and files used as parent directories. */
    public static void checkTree(List<ArchiveEntry> entries) {
        Map<String, Boolean> isDir = new HashMap<>();
        for (ArchiveEntry e : entries) {
            if (isDir.put(stripSlash(e.name()), e.directory()) != null) {
                throw new ArchiveException("duplicate entry: " + e.name());
            }
        }
        for (ArchiveEntry e : entries) {
            String n = stripSlash(e.name());
            for (int i = n.indexOf('/'); i >= 0; i = n.indexOf('/', i + 1)) {
                Boolean parentIsDir = isDir.get(n.substring(0, i));
                if (parentIsDir != null && !parentIsDir) {
                    throw new ArchiveException("file used as parent directory: " + n.substring(0, i) + " (of " + e.name() + ")");
                }
            }
        }
    }

    /** Writes the entries below {@code root}. Never overwrites and never leaves {@code root}. */
    public static void extractTo(Path root, List<ArchiveEntry> entries) throws IOException {
        checkTree(entries);
        Path base = root.toAbsolutePath().normalize();
        Files.createDirectories(base);
        for (ArchiveEntry e : entries) {
            Path target = base.resolve(stripSlash(e.name())).normalize();
            if (!target.startsWith(base) || target.equals(base)) {
                throw new ArchiveException("entry escapes the extraction root: " + e.name());
            }
            if (e.directory()) {
                Files.createDirectories(target);
            } else {
                Files.createDirectories(target.getParent());
                Files.write(target, e.data(), java.nio.file.StandardOpenOption.CREATE_NEW);
            }
        }
    }

    /** Reads a directory tree: directories end with {@code /}, parents come before children, sorted by name. */
    public static List<ArchiveEntry> snapshot(Path root) throws IOException {
        List<ArchiveEntry> out = new ArrayList<>();
        try (Stream<Path> walk = Files.walk(root)) {
            List<Path> paths = walk.filter(p -> !p.equals(root)).toList();
            Map<String, Path> byName = new java.util.TreeMap<>();
            for (Path p : paths) {
                String rel = root.relativize(p).toString().replace(java.io.File.separatorChar, '/');
                byName.put(Files.isDirectory(p) ? rel + "/" : rel, p);
            }
            for (Map.Entry<String, Path> en : byName.entrySet()) {
                out.add(new ArchiveEntry(en.getKey(), en.getKey().endsWith("/") ? new byte[0] : Files.readAllBytes(en.getValue())));
            }
        } catch (UncheckedIOException e) {
            throw e.getCause();
        }
        return out;
    }
}

package ae.arch;

import java.util.Objects;

/** Table-driven CRC-32 (IEEE 802.3, reflected polynomial 0xEDB88320) as used by ZIP. */
public final class Crc32 {
    private static final int[] TABLE = new int[256];

    static {
        for (int n = 0; n < 256; n++) {
            int c = n;
            for (int k = 0; k < 8; k++) {
                c = (c & 1) != 0 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
            }
            TABLE[n] = c;
        }
    }

    private int crc = 0xFFFFFFFF;

    /** Feeds {@code len} bytes of {@code b} starting at {@code off}. */
    public void update(byte[] b, int off, int len) {
        Objects.requireNonNull(b);
        if (off < 0 || len < 0 || off > b.length - len) {
            throw new IllegalArgumentException("range " + off + "+" + len + " outside array of " + b.length);
        }
        int c = crc;
        for (int i = off; i < off + len; i++) {
            c = TABLE[(c ^ b[i]) & 0xFF] ^ (c >>> 8);
        }
        crc = c;
    }

    /** The CRC of everything fed so far, as an unsigned 32-bit value. */
    public long value() {
        return ~crc & 0xFFFFFFFFL;
    }

    public static long of(byte[] b) {
        Crc32 c = new Crc32();
        c.update(b, 0, b.length);
        return c.value();
    }
}

package ae.arch;

import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.util.Objects;

/** Archive member name rules shared by every format; they make path traversal unrepresentable. */
public final class Names {
    private Names() {}

    /**
     * Accepts relative, normalised, slash-separated names. A single trailing slash marks a directory.
     *
     * @throws IllegalArgumentException with the reason
     */
    public static void validate(String name) {
        Objects.requireNonNull(name, "name");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("empty name");
        }
        if (name.charAt(0) == '/') {
            throw new IllegalArgumentException("absolute name: " + name);
        }
        if (name.length() >= 2 && name.charAt(1) == ':') {
            throw new IllegalArgumentException("drive prefix in name: " + name);
        }
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c < 0x20 || c == 0x7f || c == '\\') {
                throw new IllegalArgumentException("forbidden character 0x" + Integer.toHexString(c) + " in name");
            }
        }
        try {
            StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT).encode(CharBuffer.wrap(name));
        } catch (CharacterCodingException e) {
            throw new IllegalArgumentException("name is not valid Unicode", e);
        }
        String body = name.endsWith("/") ? name.substring(0, name.length() - 1) : name;
        for (String seg : body.split("/", -1)) {
            if (seg.isEmpty() || seg.equals(".") || seg.equals("..")) {
                throw new IllegalArgumentException("bad path segment '" + seg + "' in name: " + name);
            }
        }
    }

    static byte[] utf8(String s) {
        return s.getBytes(StandardCharsets.UTF_8);
    }

    /** Strict UTF-8 decoding; malformed input is an {@link ArchiveException}. */
    static String decodeUtf8(byte[] b, int off, int len) {
        try {
            return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b, off, len)).toString();
        } catch (CharacterCodingException e) {
            throw new ArchiveException("name is not valid UTF-8", e);
        }
    }
}

package ae.arch;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/** Strict POSIX ustar reader (regular files and directories). */
public final class TarReader {
    private static final int B = TarWriter.BLOCK;

    private TarReader() {}

    public static List<ArchiveEntry> read(byte[] tar) {
        return read(tar, false);
    }

    /**
     * @param stripDotSlash accept the names produced by {@code tar -c .}: drop the root entry {@code ./}
     *                      and a leading {@code ./} from every other name
     */
    public static List<ArchiveEntry> read(byte[] tar, boolean stripDotSlash) {
        if (tar.length % B != 0) {
            throw new ArchiveException("tar length " + tar.length + " is not a whole number of 512-byte blocks");
        }
        List<ArchiveEntry> out = new ArrayList<>();
        int p = 0;
        while (true) {
            if (p >= tar.length) {
                throw new ArchiveException("missing end-of-archive marker (two zero blocks)");
            }
            if (isZero(tar, p, B)) {
                if (tar.length - p < 2 * B) {
                    throw new ArchiveException("missing end-of-archive marker (two zero blocks)");
                }
                if (!isZero(tar, p, tar.length - p)) {
                    throw new ArchiveException("non-zero data after the end-of-archive marker");
                }
                break;
            }
            p = readEntry(tar, p, out, stripDotSlash);
        }
        Archives.checkTree(out);
        return out;
    }

    private static boolean isZero(byte[] b, int off, int len) {
        for (int i = off; i < off + len; i++) {
            if (b[i] != 0) {
                return false;
            }
        }
        return true;
    }

    private static int readEntry(byte[] t, int p, List<ArchiveEntry> out, boolean stripDotSlash) {
        byte[] h = Arrays.copyOfRange(t, p, p + B);
        long stored = octal(h, TarWriter.CHKSUM_OFF, 8, "checksum");
        if (stored != TarWriter.checksum(h)) {
            throw new ArchiveException("checksum mismatch in header at " + p);
        }
        if (!Arrays.equals(h, TarWriter.MAGIC_OFF, TarWriter.MAGIC_OFF + 8, ("ustar\0" + "00").getBytes(StandardCharsets.ISO_8859_1), 0, 8)) {
            throw new ArchiveException("bad magic or version (only POSIX ustar is supported) at " + p);
        }
        int type = h[TarWriter.TYPE_OFF];
        boolean dir;
        if (type == '0' || type == 0) {
            dir = false;
        } else if (type == '5') {
            dir = true;
        } else {
            throw new ArchiveException("unsupported typeflag 0x" + Integer.toHexString(type & 0xFF) + " at " + p);
        }
        octal(h, TarWriter.MODE_OFF, 8, "mode");
        octal(h, TarWriter.UID_OFF, 8, "uid");
        octal(h, TarWriter.GID_OFF, 8, "gid");
        octal(h, TarWriter.MTIME_OFF, 12, "mtime");
        long size = octal(h, TarWriter.SIZE_OFF, 12, "size");
        if (!isZero(h, TarWriter.LINK_OFF, 100)) {
            throw new ArchiveException("linkname must be empty for files and directories");
        }
        String name = text(h, TarWriter.NAME_OFF, TarWriter.NAME_LEN, "name");
        String prefix = text(h, TarWriter.PREFIX_OFF, TarWriter.PREFIX_LEN, "prefix");
        String full = prefix.isEmpty() ? name : prefix + "/" + name;
        if (dir) {
            if (size != 0) {
                throw new ArchiveException("directory " + full + " has data");
            }
            if (!full.endsWith("/")) {
                full += "/";
            }
        } else if (full.endsWith("/")) {
            throw new ArchiveException("file name ends with '/': " + full);
        }
        int dataStart = p + B;
        long blocks = (size + B - 1) / B;
        if (size > t.length - dataStart) { // length and dataStart are multiples of 512, so the padding fits too
            throw new ArchiveException("truncated data for " + full + ": declares " + size + " bytes");
        }
        int end = dataStart + (int) size;
        int next = dataStart + (int) (blocks * B);
        if (!isZero(t, end, next - end)) {
            throw new ArchiveException("non-zero padding after the data of " + full);
        }
        if (stripDotSlash) {
            if (full.equals("./")) {
                return next;
            }
            if (full.startsWith("./")) {
                full = full.substring(2);
            }
        }
        try {
            out.add(new ArchiveEntry(full, Arrays.copyOfRange(t, dataStart, end)));
        } catch (IllegalArgumentException ex) {
            throw new ArchiveException("invalid name: " + ex.getMessage(), ex);
        }
        return next;
    }

    /** NUL-terminated field; everything after the first NUL must be NUL. */
    private static String text(byte[] h, int off, int len, String what) {
        int n = 0;
        while (n < len && h[off + n] != 0) {
            n++;
        }
        if (!isZero(h, off + n, len - n)) {
            throw new ArchiveException(what + " field has data after its NUL terminator");
        }
        return Names.decodeUtf8(h, off, n);
    }

    /** Octal digits (at least one) followed only by NULs/spaces (at least one terminator byte). */
    private static long octal(byte[] h, int off, int len, String what) {
        int i = off;
        long v = 0;
        while (i < off + len && h[i] >= '0' && h[i] <= '7') {
            v = v * 8 + (h[i] - '0');
            i++;
        }
        if (i == off || i == off + len) {
            throw new ArchiveException("bad octal field: " + what);
        }
        for (int j = i; j < off + len; j++) {
            if (h[j] != 0 && h[j] != ' ') {
                throw new ArchiveException("bad octal field: " + what);
            }
        }
        return v;
    }
}

package ae.arch;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/** POSIX ustar writer: regular files and directories only, fixed owner/mtime, deterministic output. */
public final class TarWriter {
    static final int BLOCK = 512;
    static final int NAME_OFF = 0;
    static final int NAME_LEN = 100;
    static final int MODE_OFF = 100;
    static final int UID_OFF = 108;
    static final int GID_OFF = 116;
    static final int SIZE_OFF = 124;
    static final int MTIME_OFF = 136;
    static final int CHKSUM_OFF = 148;
    static final int TYPE_OFF = 156;
    static final int LINK_OFF = 157;
    static final int MAGIC_OFF = 257;
    static final int VERSION_OFF = 263;
    static final int UNAME_OFF = 265;
    static final int GNAME_OFF = 297;
    static final int DEVMAJOR_OFF = 329;
    static final int DEVMINOR_OFF = 337;
    static final int PREFIX_OFF = 345;
    static final int PREFIX_LEN = 155;

    private TarWriter() {}

    public static byte[] write(List<ArchiveEntry> entries) {
        Objects.requireNonNull(entries);
        Archives.checkTree(entries);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (ArchiveEntry e : entries) {
            byte[] data = e.data();
            out.writeBytes(header(e.name(), data.length, e.directory()));
            out.writeBytes(data);
            out.writeBytes(new byte[(BLOCK - data.length % BLOCK) % BLOCK]);
        }
        out.writeBytes(new byte[2 * BLOCK]);
        return out.toByteArray();
    }

    private static byte[] header(String name, int size, boolean dir) {
        byte[] n = Names.utf8(name);
        byte[] prefix = new byte[0];
        if (n.length > NAME_LEN) {
            int split = -1;
            // last '/' that leaves a prefix of <= 155 bytes and a non-empty rest of <= 100 bytes
            for (int i = Math.min(PREFIX_LEN, n.length - 2); i >= 1; i--) {
                if (n[i] == '/' && n.length - i - 1 <= NAME_LEN) {
                    split = i;
                    break;
                }
            }
            if (split < 0) {
                throw new IllegalArgumentException("name cannot be split into ustar prefix/name: " + name);
            }
            prefix = Arrays.copyOfRange(n, 0, split);
            n = Arrays.copyOfRange(n, split + 1, n.length);
        }
        byte[] h = new byte[BLOCK];
        System.arraycopy(n, 0, h, NAME_OFF, n.length);
        System.arraycopy(prefix, 0, h, PREFIX_OFF, prefix.length);
        octal(h, MODE_OFF, 8, dir ? 0755 : 0644);
        octal(h, UID_OFF, 8, 0);
        octal(h, GID_OFF, 8, 0);
        octal(h, SIZE_OFF, 12, size);
        octal(h, MTIME_OFF, 12, 0);
        h[TYPE_OFF] = (byte) (dir ? '5' : '0');
        System.arraycopy("ustar\0".getBytes(StandardCharsets.US_ASCII), 0, h, MAGIC_OFF, 6);
        h[VERSION_OFF] = '0';
        h[VERSION_OFF + 1] = '0';
        octal(h, DEVMAJOR_OFF, 8, 0);
        octal(h, DEVMINOR_OFF, 8, 0);
        h[CHKSUM_OFF] = ' ';
        Arrays.fill(h, CHKSUM_OFF, CHKSUM_OFF + 8, (byte) ' ');
        byte[] sum = String.format("%06o", checksum(h)).getBytes(StandardCharsets.US_ASCII);
        System.arraycopy(sum, 0, h, CHKSUM_OFF, 6);
        h[CHKSUM_OFF + 6] = 0;
        h[CHKSUM_OFF + 7] = ' ';
        return h;
    }

    /** Sum of all header bytes, taking the checksum field as eight spaces. */
    static int checksum(byte[] h) {
        int sum = 0;
        for (int i = 0; i < BLOCK; i++) {
            sum += (i >= CHKSUM_OFF && i < CHKSUM_OFF + 8) ? ' ' : (h[i] & 0xFF);
        }
        return sum;
    }

    /** {@code len - 1} zero-padded octal digits followed by a NUL. */
    private static void octal(byte[] h, int off, int len, long v) {
        String s = Long.toOctalString(v);
        if (s.length() > len - 1) {
            throw new IllegalArgumentException("value too large for a " + len + "-byte octal field: " + v);
        }
        byte[] d = ("0".repeat(len - 1 - s.length()) + s).getBytes(StandardCharsets.US_ASCII);
        System.arraycopy(d, 0, h, off, len - 1);
        h[off + len - 1] = 0;
    }
}

package ae.arch;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;

/**
 * Strict ZIP reader for classic archives. Every length and offset is validated before it is used,
 * and anything this reader does not model (ZIP64, encryption, other methods) is rejected rather than guessed.
 */
public final class ZipReader {
    /** Default cap on the declared uncompressed size of one entry. */
    public static final long DEFAULT_MAX_ENTRY_SIZE = 64L << 20;
    private static final int ALLOWED_FLAGS = 0x0002 | 0x0004 | 0x0008 | ZipWriter.FLAG_UTF8; // bits 1-2: deflate options
    private static final int FLAG_ENCRYPTED = 0x0001;
    private static final int FLAG_DESCRIPTOR = 0x0008;

    private ZipReader() {}

    private record Eocd(int pos, int entries, long cdSize, long cdOffset, int commentLen) {}

    private record Central(String name, int flags, int method, long crc, long csize, long size, long localOffset) {}

    private static int u16(byte[] b, long pos) {
        need(b, pos, 2);
        return (b[(int) pos] & 0xFF) | (b[(int) pos + 1] & 0xFF) << 8;
    }

    private static long u32(byte[] b, long pos) {
        need(b, pos, 4);
        return (u16(b, pos) | (long) u16(b, pos + 2) << 16) & 0xFFFFFFFFL;
    }

    private static void need(byte[] b, long pos, long n) {
        if (pos < 0 || n < 0 || pos + n > b.length) {
            throw new ArchiveException("truncated archive: need " + n + " bytes at " + pos + " of " + b.length);
        }
    }

    private static Eocd findEocd(byte[] z) {
        int lowest = Math.max(0, z.length - ZipWriter.EOCD_SIZE - 0xFFFF);
        for (int i = z.length - ZipWriter.EOCD_SIZE; i >= lowest; i--) {
            if (u32(z, i) == (ZipWriter.EOCD_SIG & 0xFFFFFFFFL) && i + ZipWriter.EOCD_SIZE + u16(z, i + 20) == z.length) {
                return new Eocd(i, u16(z, i + 10), u32(z, i + 12), u32(z, i + 16), u16(z, i + 20));
            }
        }
        throw new ArchiveException("end of central directory not found (comment must end exactly at end of file)");
    }

    /** The archive comment. */
    public static String comment(byte[] zip) {
        Eocd e = findEocd(zip);
        return new String(zip, e.pos + ZipWriter.EOCD_SIZE, e.commentLen, java.nio.charset.StandardCharsets.UTF_8);
    }

    public static List<ArchiveEntry> read(byte[] zip) {
        return read(zip, DEFAULT_MAX_ENTRY_SIZE);
    }

    public static List<ArchiveEntry> read(byte[] zip, long maxEntrySize) {
        Eocd e = findEocd(zip);
        if (u16(zip, e.pos + 4) != 0 || u16(zip, e.pos + 6) != 0) {
            throw new ArchiveException("multi-disk archives are not supported (disk number)");
        }
        if (u16(zip, e.pos + 8) != e.entries) {
            throw new ArchiveException("entries on this disk differ from total entries");
        }
        if (e.entries == 0xFFFF || e.cdSize == 0xFFFFFFFFL || e.cdOffset == 0xFFFFFFFFL) {
            throw new ArchiveException("zip64 archives are not supported");
        }
        if (e.cdOffset + e.cdSize != e.pos) {
            throw new ArchiveException("central directory must end exactly at the end-of-central-directory record");
        }
        List<Central> cen = readCentral(zip, e);
        checkRanges(zip, cen, (int) e.cdOffset);
        List<ArchiveEntry> out = new ArrayList<>();
        for (Central c : cen) {
            out.add(extract(zip, c, maxEntrySize, (int) e.cdOffset));
        }
        Archives.checkTree(out);
        return out;
    }

    private static List<Central> readCentral(byte[] z, Eocd e) {
        List<Central> out = new ArrayList<>();
        long p = e.cdOffset;
        long end = e.cdOffset + e.cdSize;
        for (int k = 0; k < e.entries; k++) {
            if (p + ZipWriter.CENTRAL_SIZE > end || u32(z, p) != (ZipWriter.CENTRAL_SIG & 0xFFFFFFFFL)) {
                throw new ArchiveException("bad central directory header #" + k);
            }
            int versionNeeded = u16(z, p + 6);
            int flags = u16(z, p + 8);
            int method = u16(z, p + 10);
            long crc = u32(z, p + 16);
            long csize = u32(z, p + 20);
            long size = u32(z, p + 24);
            int nlen = u16(z, p + 28);
            int elen = u16(z, p + 30);
            int clen = u16(z, p + 32);
            int disk = u16(z, p + 34);
            long off = u32(z, p + 42);
            long next = p + ZipWriter.CENTRAL_SIZE + nlen + elen + clen;
            if (next > end) {
                throw new ArchiveException("central directory header #" + k + " overruns the directory");
            }
            if ((flags & FLAG_ENCRYPTED) != 0) {
                throw new ArchiveException("encrypted entries are not supported");
            }
            if ((flags & ~ALLOWED_FLAGS) != 0) {
                throw new ArchiveException("unsupported general purpose flag bits 0x" + Integer.toHexString(flags));
            }
            if (versionNeeded > 20) {
                throw new ArchiveException("unsupported version needed: " + versionNeeded);
            }
            if (disk != 0) {
                throw new ArchiveException("multi-disk archives are not supported (entry disk)");
            }
            if (method != 0 && method != 8) {
                throw new ArchiveException("unsupported compression method " + method);
            }
            if (csize == 0xFFFFFFFFL || size == 0xFFFFFFFFL || off == 0xFFFFFFFFL) {
                throw new ArchiveException("zip64 archives are not supported (entry fields)");
            }
            if (method == 0 && csize != size) {
                throw new ArchiveException("stored entry with different compressed and uncompressed size");
            }
            String name = Names.decodeUtf8(z, (int) p + ZipWriter.CENTRAL_SIZE, nlen);
            out.add(new Central(name, flags, method, crc, csize, size, off));
            p = next;
        }
        if (p != end) {
            throw new ArchiveException("unused bytes at the end of the central directory");
        }
        return out;
    }

    /** Local header + data ranges must lie before the central directory and must not overlap. */
    private static void checkRanges(byte[] z, List<Central> cen, int cdOffset) {
        List<long[]> ranges = new ArrayList<>();
        for (Central c : cen) {
            long[] r = dataRange(z, c, cdOffset);
            ranges.add(new long[] {c.localOffset, r[1]});
        }
        ranges.sort(Comparator.comparingLong(r -> r[0]));
        for (int i = 1; i < ranges.size(); i++) {
            if (ranges.get(i)[0] < ranges.get(i - 1)[1]) {
                throw new ArchiveException("overlapping entries");
            }
        }
    }

    /** Returns {dataStart, dataEnd} after checking the local header against the central one. */
    private static long[] dataRange(byte[] z, Central c, int cdOffset) {
        long o = c.localOffset;
        if (o + ZipWriter.LOCAL_SIZE > cdOffset || u32(z, o) != (ZipWriter.LOCAL_SIG & 0xFFFFFFFFL)) {
            throw new ArchiveException("bad local header for " + c.name);
        }
        int lnlen = u16(z, o + 26);
        int lelen = u16(z, o + 28);
        if (u16(z, o + 8) != c.method) {
            throw new ArchiveException("local header method differs from central for " + c.name);
        }
        if (lnlen != Names.utf8(c.name).length
            || !Arrays.equals(z, (int) o + ZipWriter.LOCAL_SIZE, (int) o + ZipWriter.LOCAL_SIZE + lnlen,
                Names.utf8(c.name), 0, lnlen)) {
            throw new ArchiveException("local header name differs from central for " + c.name);
        }
        if ((c.flags & FLAG_DESCRIPTOR) == 0
            && (u32(z, o + 14) != c.crc || u32(z, o + 18) != c.csize || u32(z, o + 22) != c.size)) {
            throw new ArchiveException("local header crc/sizes differ from central for " + c.name);
        }
        long start = o + ZipWriter.LOCAL_SIZE + lnlen + lelen;
        long end = start + c.csize;
        if (end > cdOffset) {
            throw new ArchiveException("entry data runs into the central directory: " + c.name);
        }
        return new long[] {start, end};
    }

    private static ArchiveEntry extract(byte[] z, Central c, long maxEntrySize, int cdOffset) {
        if (c.size > maxEntrySize) {
            throw new ArchiveException("entry too large: " + c.name + " declares " + c.size + " bytes (limit " + maxEntrySize + ")");
        }
        long[] r = dataRange(z, c, cdOffset);
        int start = (int) r[0];
        byte[] data;
        if (c.method == 0) {
            data = Arrays.copyOfRange(z, start, (int) r[1]);
        } else {
            data = inflate(z, start, (int) c.csize, (int) c.size, c.name);
        }
        if (Crc32.of(data) != c.crc) {
            throw new ArchiveException("crc mismatch for " + c.name);
        }
        try {
            return new ArchiveEntry(c.name, data);
        } catch (IllegalArgumentException ex) {
            throw new ArchiveException("invalid entry: " + ex.getMessage(), ex);
        }
    }

    private static byte[] inflate(byte[] z, int start, int csize, int size, String name) {
        Inflater inf = new Inflater(true);
        try {
            inf.setInput(z, start, csize);
            byte[] out = new byte[size];
            int n = 0;
            while (n < size) {
                int got = inf.inflate(out, n, size - n);
                if (got == 0 && (inf.finished() || inf.needsInput() || inf.needsDictionary())) {
                    break;
                }
                n += got;
            }
            if (n != size) {
                throw new ArchiveException("size mismatch for " + name + ": stream ends after " + n + " of " + size + " bytes");
            }
            if (inf.inflate(new byte[1]) != 0) {
                throw new ArchiveException("size mismatch for " + name + ": stream is longer than the declared size");
            }
            if (!inf.finished()) {
                throw new ArchiveException("size mismatch for " + name + ": deflate stream not finished");
            }
            if (inf.getRemaining() != 0) {
                throw new ArchiveException("compressed data of " + name + " has " + inf.getRemaining() + " trailing bytes");
            }
            return out;
        } catch (DataFormatException ex) {
            throw new ArchiveException("corrupt deflate stream in " + name + ": " + ex.getMessage(), ex);
        } finally {
            inf.end();
        }
    }
}

package ae.arch;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.zip.Deflater;

/** Writes classic (non-ZIP64) ZIP archives with a fixed timestamp, so output is deterministic. */
public final class ZipWriter {
    /** How file data is stored. Directories are always stored. */
    public enum Method {
        STORED, DEFLATED,
        /** Deflate only when that is strictly smaller than the raw data. */
        AUTO
    }

    static final int LOCAL_SIG = 0x04034b50;
    static final int CENTRAL_SIG = 0x02014b50;
    static final int EOCD_SIG = 0x06054b50;
    static final int LOCAL_SIZE = 30;
    static final int CENTRAL_SIZE = 46;
    static final int EOCD_SIZE = 22;
    static final int FLAG_UTF8 = 0x0800;
    static final int MAX_ENTRIES = 0xFFFE; // 0xFFFF is the ZIP64 marker
    static final int DOS_DATE_1980_01_01 = (0 << 9) | (1 << 5) | 1;

    private ZipWriter() {}

    private record Member(byte[] name, int method, long crc, byte[] stored, int size, int localOffset) {}

    public static byte[] write(List<ArchiveEntry> entries, Method method, String comment) {
        Objects.requireNonNull(entries);
        Objects.requireNonNull(method);
        byte[] cm = Names.utf8(Objects.requireNonNull(comment));
        if (cm.length > 0xFFFF) {
            throw new IllegalArgumentException("comment longer than 65535 bytes");
        }
        if (entries.size() > MAX_ENTRIES) {
            throw new IllegalArgumentException("more than 65534 entries (0xFFFF is the ZIP64 marker)");
        }
        Archives.checkTree(entries);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        List<Member> members = new ArrayList<>();
        for (ArchiveEntry e : entries) {
            byte[] data = e.data();
            byte[] stored = data;
            int m = 0;
            if (!e.directory() && method != Method.STORED) {
                byte[] def = deflate(data);
                if (method == Method.DEFLATED || def.length < data.length) {
                    stored = def;
                    m = 8;
                }
            }
            byte[] name = Names.utf8(e.name());
            if (name.length > 0xFFFF) {
                throw new IllegalArgumentException("name longer than 65535 bytes");
            }
            Member mem = new Member(name, m, Crc32.of(data), stored, data.length, out.size());
            members.add(mem);
            ByteBuffer h = buffer(LOCAL_SIZE);
            h.putInt(LOCAL_SIG).putShort((short) version(m)).putShort((short) FLAG_UTF8).putShort((short) m)
                .putShort((short) 0).putShort((short) DOS_DATE_1980_01_01)
                .putInt((int) mem.crc).putInt(stored.length).putInt(mem.size)
                .putShort((short) name.length).putShort((short) 0);
            out.writeBytes(h.array());
            out.writeBytes(name);
            out.writeBytes(stored);
        }
        int cdStart = out.size();
        for (int i = 0; i < members.size(); i++) {
            Member mem = members.get(i);
            ByteBuffer h = buffer(CENTRAL_SIZE);
            h.putInt(CENTRAL_SIG).putShort((short) 20).putShort((short) version(mem.method)).putShort((short) FLAG_UTF8)
                .putShort((short) mem.method).putShort((short) 0).putShort((short) DOS_DATE_1980_01_01)
                .putInt((int) mem.crc).putInt(mem.stored.length).putInt(mem.size)
                .putShort((short) mem.name.length).putShort((short) 0).putShort((short) 0)
                .putShort((short) 0).putShort((short) 0)
                .putInt(entries.get(i).directory() ? 0x10 : 0).putInt(mem.localOffset);
            out.writeBytes(h.array());
            out.writeBytes(mem.name);
        }
        int cdSize = out.size() - cdStart;
        ByteBuffer end = buffer(EOCD_SIZE);
        end.putInt(EOCD_SIG).putShort((short) 0).putShort((short) 0).putShort((short) members.size())
            .putShort((short) members.size()).putInt(cdSize).putInt(cdStart).putShort((short) cm.length);
        out.writeBytes(end.array());
        out.writeBytes(cm);
        return out.toByteArray();
    }

    public static byte[] write(List<ArchiveEntry> entries, Method method) {
        return write(entries, method, "");
    }

    private static int version(int method) {
        return method == 8 ? 20 : 10;
    }

    private static ByteBuffer buffer(int n) {
        return ByteBuffer.allocate(n).order(ByteOrder.LITTLE_ENDIAN);
    }

    private static byte[] deflate(byte[] data) {
        Deflater d = new Deflater(Deflater.DEFAULT_COMPRESSION, true);
        try {
            d.setInput(data);
            d.finish();
            ByteArrayOutputStream o = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            while (!d.finished()) {
                o.write(buf, 0, d.deflate(buf));
            }
            return o.toByteArray();
        } finally {
            d.end();
        }
    }
}

