package ae.arch;

import static org.junit.jupiter.api.Assertions.*;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ArchivesTest {
    @Test
    void extractAndSnapshotRoundTrip(@TempDir Path dir) throws IOException {
        List<ArchiveEntry> in = TarTest.viewWithParents(TestData.random(11, 12, 1500, false));
        Path root = dir.resolve("r");
        Archives.extractTo(root, in);
        assertEquals(in, Archives.snapshot(root));
        for (ArchiveEntry e : in) {
            if (!e.directory()) {
                assertArrayEquals(e.data(), Files.readAllBytes(root.resolve(e.name())));
            }
        }
    }

    @Test
    void snapshotOrdersParentsBeforeChildren(@TempDir Path dir) throws IOException {
        Files.createDirectories(dir.resolve("b/c"));
        Files.writeString(dir.resolve("b/c/z"), "1");
        Files.writeString(dir.resolve("b/a"), "2");
        Files.writeString(dir.resolve("a"), "3");
        List<String> names = Archives.snapshot(dir).stream().map(ArchiveEntry::name).toList();
        assertEquals(List.of("a", "b/", "b/a", "b/c/", "b/c/z"), names);
    }

    @Test
    void extractRefusesToOverwrite(@TempDir Path dir) throws IOException {
        Archives.extractTo(dir, List.of(TestData.file("f", "1")));
        assertThrows(IOException.class, () -> Archives.extractTo(dir, List.of(TestData.file("f", "2"))));
        assertEquals("1", Files.readString(dir.resolve("f")));
    }

    @Test
    void extractChecksTreeBeforeWriting(@TempDir Path dir) {
        ArchiveEntry a = TestData.file("a", "1");
        assertThrows(ArchiveException.class, () -> Archives.extractTo(dir.resolve("x"), List.of(a, a)));
        assertFalse(Files.exists(dir.resolve("x")), "nothing may be written for an invalid tree");
    }

    @Test
    void zipAndTarAgree() {
        for (long seed = 0; seed < 10; seed++) {
            List<ArchiveEntry> in = TestData.random(seed, 8, 1200);
            assertEquals(ZipReader.read(ZipWriter.write(in, ZipWriter.Method.AUTO, "")), TarReader.read(TarWriter.write(in)));
        }
    }
}

package ae.arch;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import java.util.zip.CRC32;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class CrcAndNamesTest {
    @Test
    void crcCheckValue() {
        assertEquals(0xCBF43926L, Crc32.of(TestData.bytes("123456789")));
        assertEquals(0L, Crc32.of(new byte[0]));
        assertEquals(0xE8B7BE43L, Crc32.of(TestData.bytes("a")));
    }

    @Test
    void crcMatchesJdkAcrossChunking() {
        Random r = new Random(7);
        for (int round = 0; round < 200; round++) {
            byte[] b = new byte[r.nextInt(400)];
            r.nextBytes(b);
            CRC32 jdk = new CRC32();
            jdk.update(b, 0, b.length);
            Crc32 mine = new Crc32();
            int cut = b.length == 0 ? 0 : r.nextInt(b.length + 1);
            mine.update(b, 0, cut);
            mine.update(b, cut, b.length - cut);
            assertEquals(jdk.getValue(), mine.value());
            assertEquals(jdk.getValue(), Crc32.of(b));
        }
    }

    @Test
    void crcRejectsBadRange() {
        assertThrows(IllegalArgumentException.class, () -> new Crc32().update(new byte[3], 2, 2));
        assertThrows(IllegalArgumentException.class, () -> new Crc32().update(new byte[3], -1, 1));
    }

    @ParameterizedTest
    @ValueSource(strings = {"a", "a/b", "a/b/", "dir/", "naïve/日本.txt", "a b", "a..b", ".hidden", "a/.b", "..x", "ab:c"})
    void validNames(String n) {
        assertDoesNotThrow(() -> Names.validate(n));
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "/", "/abs", "a//b", "../x", "a/../b", "a/..", "./a", "a/./b", "..", ".", "a\\b",
        "a\u0000b", "a\nb", "C:x", "c:/x", "a//", "//", "a/\t", "a\u007fb"})
    void invalidNames(String n) {
        assertThrows(IllegalArgumentException.class, () -> Names.validate(n), n);
    }

    @Test
    void rejectionReasonsAreNamed() {
        // "/abs" would also fail the empty-segment rule; the message shows which rule fired first
        assertTrue(assertThrows(IllegalArgumentException.class, () -> Names.validate("/abs")).getMessage().contains("absolute"));
        assertTrue(assertThrows(IllegalArgumentException.class, () -> Names.validate("a/../b")).getMessage().contains("segment"));
        assertTrue(assertThrows(IllegalArgumentException.class, () -> Names.validate("")).getMessage().contains("empty"));
        assertTrue(assertThrows(IllegalArgumentException.class, () -> Names.validate("a\\b")).getMessage().contains("forbidden"));
    }

    @Test
    void loneSurrogateRejected() {
        assertThrows(IllegalArgumentException.class, () -> Names.validate("a\uD800b"));
        assertDoesNotThrow(() -> Names.validate("a\uD83D\uDE00b")); // control: a valid pair
        assertThrows(NullPointerException.class, () -> Names.validate(null));
    }

    @Test
    void entryCopiesAndValidates() {
        byte[] src = {1, 2, 3};
        ArchiveEntry e = new ArchiveEntry("a", src);
        src[0] = 9;
        assertEquals(1, e.data()[0]);
        e.data()[1] = 9;
        assertEquals(2, e.data()[1]);
        assertEquals(e, new ArchiveEntry("a", new byte[] {1, 2, 3}));
        assertEquals(e.hashCode(), new ArchiveEntry("a", new byte[] {1, 2, 3}).hashCode());
        assertNotEquals(e, new ArchiveEntry("a", new byte[] {1, 2, 4}));
        assertNotEquals(e, new ArchiveEntry("b", new byte[] {1, 2, 3}));
        assertFalse(e.directory());
        assertTrue(new ArchiveEntry("d/", new byte[0]).directory());
        assertThrows(IllegalArgumentException.class, () -> new ArchiveEntry("d/", new byte[1]));
        assertThrows(IllegalArgumentException.class, () -> new ArchiveEntry("../x", new byte[0]));
    }

    @Test
    void treeChecks() {
        ArchiveEntry a = TestData.file("a", "x");
        assertDoesNotThrow(() -> Archives.checkTree(java.util.List.of(a, TestData.file("b", "y"))));
        assertDoesNotThrow(() -> Archives.checkTree(java.util.List.of(new ArchiveEntry("d/", new byte[0]), TestData.file("d/x", "y"))));
        assertDoesNotThrow(() -> Archives.checkTree(java.util.List.of(TestData.file("d/x", "y")))); // implicit parent
        var dup = assertThrows(ArchiveException.class, () -> Archives.checkTree(java.util.List.of(a, a)));
        assertTrue(dup.getMessage().contains("duplicate"), dup.getMessage());
        var dupDir = assertThrows(ArchiveException.class,
            () -> Archives.checkTree(java.util.List.of(a, new ArchiveEntry("a/", new byte[0]))));
        assertTrue(dupDir.getMessage().contains("duplicate"), dupDir.getMessage());
        var parent = assertThrows(ArchiveException.class,
            () -> Archives.checkTree(java.util.List.of(a, TestData.file("a/b", "y"))));
        assertTrue(parent.getMessage().contains("parent"), parent.getMessage());
        // order must not matter
        assertThrows(ArchiveException.class, () -> Archives.checkTree(java.util.List.of(TestData.file("a/b/c", "y"), a)));
    }
}

package ae.arch;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.TreeMap;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarTest {
    private static final List<ArchiveEntry> THREE = List.of(
        TestData.file("hello.txt", "hello tar"),
        new ArchiveEntry("dir/", new byte[0]),
        TestData.file("dir/big.bin", "0123456789".repeat(100))); // 1000 bytes -> 2 data blocks

    private static void assertRejected(byte[] t, String fragment) {
        ArchiveException ex = assertThrows(ArchiveException.class, () -> TarReader.read(t));
        assertTrue(ex.getMessage().toLowerCase().contains(fragment), "expected '" + fragment + "' in: " + ex.getMessage());
    }

    /** Recomputes the checksum of the header at {@code off} so a crafted field change stays "valid" otherwise. */
    private static void reseal(byte[] t, int off) {
        Arrays.fill(t, off + 148, off + 156, (byte) ' ');
        int sum = 0;
        for (int i = 0; i < 512; i++) {
            sum += t[off + i] & 0xFF;
        }
        byte[] f = String.format("%06o", sum).getBytes(StandardCharsets.US_ASCII);
        System.arraycopy(f, 0, t, off + 148, 6);
        t[off + 154] = 0;
        t[off + 155] = ' ';
    }

    @Test
    void exactLayoutOfOneFile() {
        byte[] t = TarWriter.write(List.of(TestData.file("a.txt", "hi")));
        assertEquals(512 + 512 + 1024, t.length); // header + one data block + two zero blocks
        assertEquals("a.txt", new String(t, 0, 5, StandardCharsets.US_ASCII));
        assertEquals(0, t[5]);
        assertEquals("0000644\0", new String(t, 100, 8, StandardCharsets.US_ASCII));
        assertEquals("0000000\0", new String(t, 108, 8, StandardCharsets.US_ASCII));
        assertEquals("00000000002\0", new String(t, 124, 12, StandardCharsets.US_ASCII)); // size 2
        assertEquals("00000000000\0", new String(t, 136, 12, StandardCharsets.US_ASCII)); // mtime 0
        assertEquals('0', t[156]);
        assertEquals("ustar\0", new String(t, 257, 6, StandardCharsets.ISO_8859_1));
        assertEquals("00", new String(t, 263, 2, StandardCharsets.US_ASCII));
        int sum = 0;
        for (int i = 0; i < 512; i++) {
            sum += (i >= 148 && i < 156) ? ' ' : (t[i] & 0xFF);
        }
        assertEquals(String.format("%06o", sum), new String(t, 148, 6, StandardCharsets.US_ASCII));
        assertEquals(0, t[154]);
        assertEquals(' ', t[155]);
        assertEquals("hi", new String(t, 512, 2, StandardCharsets.US_ASCII));
        for (int i = 514; i < t.length; i++) {
            assertEquals(0, t[i], "padding/end byte " + i);
        }
        // literal sum, byte values added by hand: name 97+46+116+120+116=495, mode/uid/gid/devmajor/devminor
        // (sum of all 512 header bytes, checksum field counted as 8 spaces) = 4206 = octal 10156
        // name 495 + mode 350 + uid 336 + gid 336 + size("00000000002") 530 + mtime 528 + chksum 8 spaces 256
        // + typeflag '0' 48 + "ustar" 559 + "00" 96 + devmajor 336 + devminor 336 = 4206
        assertEquals(4206, sum);
        assertEquals("010156", new String(t, 148, 6, StandardCharsets.US_ASCII));
    }

    @Test
    void directoryHeader() {
        byte[] t = TarWriter.write(List.of(new ArchiveEntry("d/", new byte[0])));
        assertEquals(512 + 1024, t.length);
        assertEquals('5', t[156]);
        assertEquals("0000755\0", new String(t, 100, 8, StandardCharsets.US_ASCII));
        assertEquals("00000000000\0", new String(t, 124, 12, StandardCharsets.US_ASCII));
        assertEquals("d/", new String(t, 0, 2, StandardCharsets.US_ASCII));
    }

    @Test
    void roundTrip() {
        for (long seed = 0; seed < 25; seed++) {
            List<ArchiveEntry> in = TestData.random(seed, 1 + (int) seed % 9, 2500);
            byte[] t = TarWriter.write(in);
            assertEquals(0, t.length % 512);
            assertEquals(in, TarReader.read(t), "seed " + seed);
        }
        assertEquals(List.of(), TarReader.read(TarWriter.write(List.of())));
        assertEquals(1024, TarWriter.write(List.of()).length);
    }

    @Test
    void exactBlockMultipleDataHasNoExtraBlock() {
        byte[] t = TarWriter.write(List.of(new ArchiveEntry("f", new byte[512])));
        assertEquals(512 + 512 + 1024, t.length);
        byte[] t2 = TarWriter.write(List.of(new ArchiveEntry("f", new byte[513])));
        assertEquals(512 + 1024 + 1024, t2.length);
        assertEquals(513, TarReader.read(t2).get(0).data().length);
    }

    @Test
    void longNamesUsePrefix() {
        String seg = "s".repeat(49); // each segment + "/" = 50 bytes
        for (int segments = 1; segments <= 4; segments++) {
            StringBuilder b = new StringBuilder();
            for (int i = 0; i < segments; i++) {
                b.append(seg).append('/');
            }
            String name = b + "f"; // length 50*segments + 1
            List<ArchiveEntry> in = List.of(TestData.file(name, "x"));
            byte[] t = TarWriter.write(in);
            boolean usesPrefix = t[345] != 0;
            assertEquals(name.length() > 100, usesPrefix, "length " + name.length());
            assertEquals(in, TarReader.read(t), "length " + name.length());
        }
        // 5 x 50 + 1 = 251 bytes: the only slashes leave prefix > 155 or rest > 100
        String five = (seg + "/").repeat(5) + "f";
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(TestData.file(five, ""))));
        // exactly 100 bytes: no prefix; exactly 101: needs the split
        String hundred = "a".repeat(100);
        assertEquals(0, TarWriter.write(List.of(TestData.file(hundred, ""))) [345]);
        String d = "d".repeat(100) + "/" + "e"; // 102 bytes, prefix 100, name 1
        byte[] t = TarWriter.write(List.of(TestData.file(d, "")));
        assertEquals("d".repeat(100), new String(t, 345, 100, StandardCharsets.US_ASCII));
        assertEquals("e", new String(t, 0, 1, StandardCharsets.US_ASCII));
        // longest legal: prefix 155 + '/' + name 100 = 256 bytes
        String longest = "p".repeat(155) + "/" + "n".repeat(100);
        assertEquals(256, longest.length());
        assertEquals(List.of(TestData.file(longest, "z")), TarReader.read(TarWriter.write(List.of(TestData.file(longest, "z")))));
        // one byte more in either part cannot be represented
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(TestData.file("p".repeat(156) + "/" + "n".repeat(100), ""))));
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(TestData.file("p".repeat(155) + "/" + "n".repeat(101), ""))));
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(TestData.file("n".repeat(101), ""))));
        // a trailing slash of a directory never becomes the split point
        String dirName = "q".repeat(101) + "/";
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(new ArchiveEntry(dirName, new byte[0]))));
        String dir2 = "q".repeat(60) + "/" + "r".repeat(60) + "/";
        assertEquals(List.of(new ArchiveEntry(dir2, new byte[0])), TarReader.read(TarWriter.write(List.of(new ArchiveEntry(dir2, new byte[0])))));
    }

    @Test
    void byteLengthNotCharLengthCounts() {
        String name = "é".repeat(60); // 120 UTF-8 bytes, no slash -> cannot be split
        assertThrows(IllegalArgumentException.class, () -> TarWriter.write(List.of(TestData.file(name, ""))));
        String ok = "é".repeat(20) + "/" + "é".repeat(40); // 40 + 1 + 80 bytes
        assertEquals(List.of(TestData.file(ok, "k")), TarReader.read(TarWriter.write(List.of(TestData.file(ok, "k")))));
    }

    @Test
    void writerRejectsBadTrees() {
        ArchiveEntry a = TestData.file("a", "1");
        assertThrows(ArchiveException.class, () -> TarWriter.write(List.of(a, a)));
        assertThrows(ArchiveException.class, () -> TarWriter.write(List.of(a, TestData.file("a/b", "1"))));
    }

    // ---- differential against GNU tar ----

    private static boolean tool(String... cmd) {
        try {
            Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
            p.getInputStream().readAllBytes();
            return p.waitFor() == 0;
        } catch (IOException | InterruptedException e) {
            return false;
        }
    }

    private static String run(Path cwd, String... cmd) throws IOException, InterruptedException {
        Process p = new ProcessBuilder(cmd).directory(cwd.toFile()).redirectErrorStream(true).start();
        String out = new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        assertEquals(0, p.waitFor(), String.join(" ", cmd) + "\n" + out);
        return out;
    }

    @Test
    void gnuTarReadsOurArchives(@TempDir Path dir) throws Exception {
        assumeTrue(tool("tar", "--version"), "tar not installed");
        for (long seed = 0; seed < 5; seed++) {
            List<ArchiveEntry> in = TestData.random(900 + seed, 12, 3000, false);
            // add a prefix-split name and an empty directory
            String longName = ("L".repeat(60) + "/").repeat(3) + "deep.txt";
            in = new java.util.ArrayList<>(in);
            in.add(TestData.file(longName, "deep " + seed));
            in.add(new ArchiveEntry("emptydir/", new byte[0]));
            Path f = dir.resolve("t" + seed + ".tar");
            Files.write(f, TarWriter.write(in));
            String listing = run(dir, "tar", "-tf", f.toString());
            for (ArchiveEntry e : in) {
                assertTrue(Arrays.asList(listing.split("\n")).contains(e.name()), e.name() + " missing in:\n" + listing);
            }
            Path out = dir.resolve("out" + seed);
            Files.createDirectories(out);
            run(dir, "tar", "-xf", f.toString(), "-C", out.toString());
            assertEquals(viewWithParents(in), Archives.snapshot(out), "seed " + seed);
        }
    }

    static List<ArchiveEntry> viewWithParents(List<ArchiveEntry> in) {
        TreeMap<String, ArchiveEntry> map = new TreeMap<>();
        for (ArchiveEntry e : in) {
            String[] parts = e.name().split("/");
            StringBuilder p = new StringBuilder();
            for (int i = 0; i < parts.length - 1; i++) {
                p.append(parts[i]).append('/');
                map.putIfAbsent(p.toString(), new ArchiveEntry(p.toString(), new byte[0]));
            }
            map.put(e.name(), e);
        }
        return new java.util.ArrayList<>(map.values());
    }

    @Test
    void weReadGnuTarUstarArchives(@TempDir Path dir) throws Exception {
        assumeTrue(tool("tar", "--version"), "tar not installed");
        for (long seed = 0; seed < 5; seed++) {
            Path src = dir.resolve("src" + seed);
            List<ArchiveEntry> in = new java.util.ArrayList<>(TestData.random(500 + seed, 10, 3000, false));
            in.add(TestData.file(("M".repeat(70) + "/").repeat(2) + "n" + seed, "long " + seed));
            Archives.extractTo(src, in);
            Path t = dir.resolve("g" + seed + ".tar");
            run(src, "tar", "--format=ustar", "--numeric-owner", "-cf", t.toString(), ".");
            List<ArchiveEntry> got = TarReader.read(Files.readAllBytes(t), true);
            assertEquals(viewWithParents(in), sortedWithoutDot(got), "seed " + seed);
        }
    }

    private static List<ArchiveEntry> sortedWithoutDot(List<ArchiveEntry> got) {
        TreeMap<String, ArchiveEntry> map = new TreeMap<>();
        for (ArchiveEntry e : got) {
            map.put(e.name(), e);
        }
        assertEquals(got.size(), map.size());
        return new java.util.ArrayList<>(map.values());
    }

    // ---- strictness ----

    @Test
    void controlLoads() {
        assertEquals(THREE, TarReader.read(TarWriter.write(THREE)));
    }

    @Test
    void headerDefectsRejected() {
        byte[] t = TarWriter.write(THREE);
        byte[] badSum = t.clone();
        badSum[0] ^= 1;
        assertRejected(badSum, "checksum");
        byte[] magic = t.clone();
        magic[257] = 'x';
        reseal(magic, 0);
        assertRejected(magic, "magic");
        byte[] ver = t.clone();
        ver[263] = '1';
        reseal(ver, 0);
        assertRejected(ver, "magic");
        byte[] link = t.clone();
        link[156] = '2'; // symlink
        reseal(link, 0);
        assertRejected(link, "typeflag");
        byte[] pax = t.clone();
        pax[156] = 'x';
        reseal(pax, 0);
        assertRejected(pax, "typeflag");
        byte[] nul = t.clone();
        nul[156] = 0; // old-style regular file marker is accepted
        reseal(nul, 0);
        assertEquals(THREE, TarReader.read(nul));
        byte[] octal = t.clone();
        octal[124] = '9'; // size not octal
        reseal(octal, 0);
        assertRejected(octal, "octal");
        byte[] mode = t.clone();
        mode[100] = 'z';
        reseal(mode, 0);
        assertRejected(mode, "octal");
        byte[] noTerminator = t.clone();
        System.arraycopy("00000644".getBytes(StandardCharsets.US_ASCII), 0, noTerminator, 100, 8); // 8 digits, no NUL
        reseal(noTerminator, 0);
        assertRejected(noTerminator, "octal");
        byte[] linkname = t.clone();
        linkname[157] = 'x';
        reseal(linkname, 0);
        assertRejected(linkname, "linkname");
        byte[] name = t.clone();
        name[10] = 'x'; // data after the NUL terminator of the name
        reseal(name, 0);
        assertRejected(name, "name");
        byte[] trav = t.clone();
        trav[0] = '/';
        reseal(trav, 0);
        assertRejected(trav, "name");
        byte[] dirSize = t.clone();
        int dirHeader = 512 + 512; // hello.txt header + 1 data block
        dirSize[dirHeader + 124 + 10] = '1';
        reseal(dirSize, dirHeader);
        assertRejected(dirSize, "directory");
        byte[] emptyDirAsFile = t.clone();
        emptyDirAsFile[1024 + TarWriter.TYPE_OFF] = '0'; // the "dir/" header says regular file, size 0
        reseal(emptyDirAsFile, 1024);
        assertRejected(emptyDirAsFile, "ends with");
        byte[] slashFile = t.clone();
        slashFile[8] = '/'; // "hello.tx/"
        reseal(slashFile, 0);
        assertRejected(slashFile, "name");
    }

    @Test
    void structureDefectsRejected() {
        byte[] t = TarWriter.write(THREE);
        byte[] pad = t.clone();
        pad[512 + 9] = 1; // inside the padding of the first data block ("hello tar" is 9 bytes)
        assertRejected(pad, "padding");
        byte[] notBlocks = Arrays.copyOf(t, t.length + 1);
        assertRejected(notBlocks, "block");
        byte[] garbageAfterEnd = Arrays.copyOf(t, t.length + 512);
        garbageAfterEnd[t.length + 3] = 7;
        assertRejected(garbageAfterEnd, "end");
        byte[] zeroPad = Arrays.copyOf(t, 10240); // GNU tar pads to a 10240 record: accepted
        assertEquals(THREE, TarReader.read(zeroPad));
        byte[] oneZeroBlock = Arrays.copyOf(t, t.length - 512);
        assertRejected(oneZeroBlock, "end");
        byte[] noEnd = Arrays.copyOf(t, t.length - 1024);
        assertRejected(noEnd, "end");
        byte[] hugeSize = t.clone();
        System.arraycopy("77777777777\0".getBytes(StandardCharsets.US_ASCII), 0, hugeSize, 124, 12);
        reseal(hugeSize, 0);
        assertRejected(hugeSize, "truncated");
    }

    @Test
    void duplicateAndTreeConflictsRejected() {
        byte[] t = TarWriter.write(List.of(TestData.file("aa", "1"), TestData.file("bb", "2")));
        assertEquals(2, TarReader.read(t).size());
        byte[] dup = t.clone();
        int second = 1024;
        dup[second] = 'a';
        dup[second + 1] = 'a';
        reseal(dup, second);
        ArchiveException ex = assertThrows(ArchiveException.class, () -> TarReader.read(dup));
        assertTrue(ex.getMessage().contains("duplicate"), ex.getMessage());
    }

    @Test
    void everyTruncationRejected() {
        byte[] t = TarWriter.write(THREE);
        for (int n = 0; n < t.length; n++) {
            int len = n;
            byte[] cut = Arrays.copyOf(t, len);
            assertThrows(ArchiveException.class, () -> TarReader.read(cut), "truncated to " + len);
        }
    }

    @Test
    void everyByteFlipRejectedExceptFileData() {
        byte[] t = TarWriter.write(THREE);
        // layout: hello header 0..511, its data 512..520 (9 bytes) + padding; dir header 1024; big header 1536;
        // big data 2048..3047 (1000 bytes) + padding to 3071; two zero blocks 3072..4095
        for (int i = 0; i < t.length; i++) {
            boolean data = (i >= 512 && i < 521) || (i >= 2048 && i < 3048);
            for (int bit : new int[] {0, 6}) {
                byte[] f = t.clone();
                f[i] ^= (byte) (1 << bit);
                if (data) { // tar has no data checksum: accepted, and exactly this byte differs
                    List<ArchiveEntry> got = TarReader.read(f);
                    int differing = 0;
                    for (int k = 0; k < THREE.size(); k++) {
                        byte[] x = THREE.get(k).data();
                        byte[] y = got.get(k).data();
                        assertEquals(x.length, y.length);
                        for (int j = 0; j < x.length; j++) {
                            differing += x[j] != y[j] ? 1 : 0;
                        }
                    }
                    assertEquals(1, differing, "flip " + i);
                } else {
                    int at = i;
                    assertThrows(ArchiveException.class, () -> TarReader.read(f), "flip byte " + at + " bit " + bit + " must be rejected");
                }
            }
        }
    }
}

package ae.arch;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;

/** Deterministic random archive contents whose names never conflict. */
final class TestData {
    private TestData() {}

    static byte[] bytes(String s) {
        return s.getBytes(StandardCharsets.UTF_8);
    }

    static ArchiveEntry file(String name, String content) {
        return new ArchiveEntry(name, bytes(content));
    }

    /** Mix of compressible and incompressible content, length 0..max. */
    static byte[] content(Random r, int max) {
        int n = r.nextInt(max + 1);
        byte[] b = new byte[n];
        if (r.nextBoolean()) {
            r.nextBytes(b);
        } else {
            for (int i = 0; i < n; i++) {
                b[i] = (byte) ('a' + (i / 7) % 3);
            }
        }
        return b;
    }

    /** Files are named "f{i}.ext" (unique), directories "d{0..2}" are separate names, so no file is ever a parent. */
    static List<ArchiveEntry> random(long seed, int count, int maxLen) {
        return random(seed, count, maxLen, true);
    }

    /** {@code unicode=false} keeps names ASCII for tests that touch the file system (the CI locale may be POSIX). */
    static List<ArchiveEntry> random(long seed, int count, int maxLen, boolean unicode) {
        Random r = new Random(seed);
        List<ArchiveEntry> out = new ArrayList<>();
        Set<String> dirs = new HashSet<>();
        String[] stems = unicode
            ? new String[] {"", "d0/", "d1/", "d0/s/", "naïve/", "日本/x/"}
            : new String[] {"", "d0/", "d1/", "d0/s/", "naive/", "jp/x/"};
        for (int i = 0; i < count; i++) {
            String stem = stems[r.nextInt(stems.length)];
            if (!stem.isEmpty() && dirs.add(stem) && r.nextBoolean()) {
                out.add(new ArchiveEntry(stem, new byte[0]));
            }
            out.add(new ArchiveEntry(stem + "f" + i + (r.nextBoolean() ? ".txt" : ""), content(r, maxLen)));
        }
        return out;
    }
}

package ae.arch;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import ae.arch.ZipWriter.Method;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ZipTest {
    private static final List<ArchiveEntry> THREE = List.of(
        TestData.file("ab/cde", "hello hello hello hello"),
        new ArchiveEntry("dir/", new byte[0]),
        TestData.file("dir/x.txt", "x".repeat(300)));

    private static ByteBuffer le(byte[] b) {
        return ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);
    }

    private static int eocd(byte[] z) {
        for (int i = z.length - 22; i >= 0; i--) {
            if (le(z).getInt(i) == 0x06054b50) {
                return i;
            }
        }
        throw new AssertionError("no eocd");
    }

    /** Offset of the central header of entry k (entries all have no extra/comment fields). */
    private static int central(byte[] z, int k) {
        int p = le(z).getInt(eocd(z) + 16);
        for (int i = 0; i < k; i++) {
            p += 46 + le(z).getShort(p + 28) + le(z).getShort(p + 30) + le(z).getShort(p + 32);
        }
        return p;
    }

    private static int local(byte[] z, int k) {
        return le(z).getInt(central(z, k) + 42);
    }

    private static byte[] zip(List<ArchiveEntry> e, Method m) {
        return ZipWriter.write(e, m, "");
    }

    private static void assertRejected(byte[] z, String fragment) {
        ArchiveException ex = assertThrows(ArchiveException.class, () -> ZipReader.read(z));
        assertTrue(ex.getMessage().toLowerCase().contains(fragment), "expected '" + fragment + "' in: " + ex.getMessage());
    }

    @Test
    void exactLayoutOfOneStoredFile() {
        byte[] z = ZipWriter.write(List.of(TestData.file("a.txt", "hi")), Method.STORED, "");
        // local 30 + name 5 + data 2 = 37; central 46 + 5 = 51; eocd 22 -> 37 + 51 + 22 = 110
        assertEquals(110, z.length);
        ByteBuffer b = le(z);
        assertEquals(0x04034b50, b.getInt(0));
        assertEquals(10, b.getShort(4));        // version needed for stored
        assertEquals(0x0800, b.getShort(6));    // UTF-8 flag only
        assertEquals(0, b.getShort(8));         // method stored
        assertEquals(0, b.getShort(10));        // dos time 00:00:00
        assertEquals(0x21, b.getShort(12));     // dos date 1980-01-01: (0<<9)|(1<<5)|1
        assertEquals(Crc32.of(TestData.bytes("hi")), b.getInt(14) & 0xFFFFFFFFL);
        assertEquals(2, b.getInt(18));
        assertEquals(2, b.getInt(22));
        assertEquals(5, b.getShort(26));
        assertEquals(0, b.getShort(28));
        assertEquals("a.txt", new String(z, 30, 5, StandardCharsets.US_ASCII));
        assertEquals("hi", new String(z, 35, 2, StandardCharsets.US_ASCII));
        assertEquals(0x02014b50, b.getInt(37));
        assertEquals(0, b.getInt(37 + 42));     // local offset
        assertEquals(0x06054b50, b.getInt(88));
        assertEquals(1, b.getShort(88 + 8));
        assertEquals(1, b.getShort(88 + 10));
        assertEquals(51, b.getInt(88 + 12));
        assertEquals(37, b.getInt(88 + 16));
        assertEquals(0, b.getShort(88 + 20));
    }

    @Test
    void roundTripAllMethods() {
        for (Method m : Method.values()) {
            for (long seed = 0; seed < 25; seed++) {
                List<ArchiveEntry> in = TestData.random(seed, 1 + (int) seed % 9, 2500);
                assertEquals(in, ZipReader.read(zip(in, m)), m + " seed " + seed);
            }
        }
        assertEquals(List.of(), ZipReader.read(zip(List.of(), Method.AUTO)));
    }

    @Test
    void methodsAreWhatTheyClaim() {
        byte[] data = "z".repeat(500).getBytes(StandardCharsets.UTF_8);
        byte[] noise = new byte[200];
        new java.util.Random(5).nextBytes(noise);
        List<ArchiveEntry> e = List.of(new ArchiveEntry("zeros", data), new ArchiveEntry("noise", noise), new ArchiveEntry("d/", new byte[0]));
        byte[] stored = zip(e, Method.STORED);
        byte[] deflated = zip(e, Method.DEFLATED);
        byte[] auto = zip(e, Method.AUTO);
        assertEquals(0, le(stored).getShort(central(stored, 0) + 10));
        assertEquals(8, le(deflated).getShort(central(deflated, 0) + 10));
        assertEquals(8, le(deflated).getShort(central(deflated, 1) + 10));
        assertEquals(0, le(deflated).getShort(central(deflated, 2) + 10), "directories are always stored");
        assertEquals(8, le(auto).getShort(central(auto, 0) + 10), "compressible -> deflate");
        assertEquals(0, le(auto).getShort(central(auto, 1) + 10), "incompressible -> stored");
        assertEquals(20, le(deflated).getShort(central(deflated, 0) + 6));
        assertTrue(deflated.length < stored.length + 200);
        assertTrue(auto.length < stored.length);
    }

    @Test
    void autoStoresWhenDeflateIsNotStrictlySmaller() {
        // find, with the JDK deflater, a payload whose deflated size equals its raw size (the tie case)
        byte[] tie = null;
        for (int n = 1; n < 300 && tie == null; n++) {
            byte[] cand = new byte[n];
            new java.util.Random(n).nextBytes(cand);
            for (int i = 0; i < n; i += 2) {
                cand[i] = 'a'; // half predictable: sizes hover around n
            }
            java.util.zip.Deflater d = new java.util.zip.Deflater(java.util.zip.Deflater.DEFAULT_COMPRESSION, true);
            d.setInput(cand);
            d.finish();
            byte[] buf = new byte[n + 64];
            int got = d.deflate(buf);
            d.end();
            if (got == n) {
                tie = cand;
            }
        }
        assertNotNull(tie, "fixture search must find a deflated-size == raw-size payload");
        byte[] z = zip(List.of(new ArchiveEntry("tie", tie)), Method.AUTO);
        assertEquals(0, le(z).getShort(central(z, 0) + 10), "tie -> stored");
        assertEquals(tie.length, le(z).getInt(central(z, 0) + 20));
    }

    @Test
    void emptyAndTinyFilesRoundTripDeflated() {
        List<ArchiveEntry> e = List.of(new ArchiveEntry("empty", new byte[0]), new ArchiveEntry("one", new byte[] {7}));
        byte[] z = zip(e, Method.DEFLATED);
        assertEquals(8, le(z).getShort(central(z, 0) + 10));
        assertEquals(e, ZipReader.read(z));
    }

    @Test
    void externalAttributesMarkDirectories() {
        byte[] z = zip(THREE, Method.STORED);
        assertEquals(0, le(z).getInt(central(z, 0) + 38));
        assertEquals(0x10, le(z).getInt(central(z, 1) + 38), "MS-DOS directory bit");
        assertEquals(0, le(z).getInt(central(z, 2) + 38));
    }

    @Test
    void commentRoundTripAndLimits() {
        byte[] z = ZipWriter.write(THREE, Method.AUTO, "héllo");
        assertEquals("héllo", ZipReader.comment(z));
        assertEquals(THREE, ZipReader.read(z));
        String max = "c".repeat(65535);
        assertEquals(max, ZipReader.comment(ZipWriter.write(List.of(), Method.STORED, max)));
        assertThrows(IllegalArgumentException.class, () -> ZipWriter.write(List.of(), Method.STORED, "c".repeat(65536)));
        assertThrows(NullPointerException.class, () -> ZipWriter.write(THREE, null, ""));
    }

    @Test
    void fakeEocdInsideCommentIsSkipped() {
        // the comment holds a full-looking EOCD signature; only the real one ends exactly at EOF
        String comment = "PK\u0005\u0006" + "\u0000".repeat(30);
        byte[] z = ZipWriter.write(THREE, Method.STORED, comment);
        assertEquals(THREE, ZipReader.read(z));
        assertEquals(comment, ZipReader.comment(z));
    }

    @Test
    void writerRejectsBadTrees() {
        ArchiveEntry a = TestData.file("a", "1");
        assertThrows(ArchiveException.class, () -> zip(List.of(a, a), Method.STORED));
        assertThrows(ArchiveException.class, () -> zip(List.of(a, TestData.file("a/b", "1")), Method.STORED));
        List<ArchiveEntry> many = new ArrayList<>();
        for (int i = 0; i < 65535; i++) {
            many.add(new ArchiveEntry("f" + i, new byte[0]));
        }
        // 0xFFFF in the entry count is the ZIP64 marker, so 65534 is the most a classic archive can hold
        assertThrows(IllegalArgumentException.class, () -> zip(many, Method.STORED));
        assertEquals(65534, ZipReader.read(zip(many.subList(0, 65534), Method.STORED)).size()); // control
    }

    // ---- differential against the JDK and Info-ZIP ----

    @Test
    void jdkReadsOurArchives(@TempDir Path dir) throws IOException {
        for (Method m : Method.values()) {
            List<ArchiveEntry> in = TestData.random(100 + m.ordinal(), 12, 3000);
            byte[] z = zip(in, m);
            List<ArchiveEntry> viaStream = new ArrayList<>();
            try (ZipInputStream zin = new ZipInputStream(new ByteArrayInputStream(z))) {
                for (ZipEntry e; (e = zin.getNextEntry()) != null; ) {
                    viaStream.add(new ArchiveEntry(e.getName(), zin.readAllBytes()));
                }
            }
            assertEquals(in, viaStream, "ZipInputStream " + m);
            Path f = dir.resolve(m + ".zip");
            Files.write(f, z);
            List<ArchiveEntry> viaFile = new ArrayList<>();
            try (ZipFile zf = new ZipFile(f.toFile())) {
                for (var en = zf.entries(); en.hasMoreElements(); ) {
                    ZipEntry e = en.nextElement();
                    try (var is = zf.getInputStream(e)) {
                        viaFile.add(new ArchiveEntry(e.getName(), is.readAllBytes()));
                    }
                    assertEquals(e.getName().endsWith("/"), e.isDirectory());
                }
            }
            assertEquals(in, viaFile, "ZipFile " + m);
        }
    }

    @Test
    void weReadJdkArchivesIncludingDataDescriptors() throws IOException {
        List<ArchiveEntry> in = TestData.random(321, 14, 3000);
        ByteArrayOutputStream bo = new ByteArrayOutputStream();
        try (ZipOutputStream zo = new ZipOutputStream(bo)) {
            int i = 0;
            for (ArchiveEntry e : in) {
                ZipEntry ze = new ZipEntry(e.name());
                if (i++ % 3 == 0 && !e.directory()) { // STORED needs size and crc up front
                    ze.setMethod(ZipEntry.STORED);
                    ze.setSize(e.data().length);
                    ze.setCompressedSize(e.data().length);
                    ze.setCrc(Crc32.of(e.data()));
                }
                zo.putNextEntry(ze);
                zo.write(e.data());
                zo.closeEntry();
            }
        }
        byte[] z = bo.toByteArray();
        boolean sawDescriptor = false;
        for (int k = 0; k < in.size(); k++) {
            sawDescriptor |= (le(z).getShort(local(z, k) + 6) & 8) != 0;
        }
        assertTrue(sawDescriptor, "fixture must contain a bit-3 entry");
        assertEquals(in, ZipReader.read(z));
    }

    private static boolean tool(String... cmd) {
        try {
            Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
            p.getInputStream().readAllBytes();
            return p.waitFor() == 0;
        } catch (IOException | InterruptedException e) {
            return false;
        }
    }

    private static String run(Path cwd, String... cmd) throws IOException, InterruptedException {
        Process p = new ProcessBuilder(cmd).directory(cwd.toFile()).redirectErrorStream(true).start();
        String out = new String(p.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        assertEquals(0, p.waitFor(), String.join(" ", cmd) + "\n" + out);
        return out;
    }

    @Test
    void unzipAcceptsOurArchives(@TempDir Path dir) throws Exception {
        assumeTrue(tool("unzip", "-v"), "unzip not installed");
        for (Method m : Method.values()) {
            List<ArchiveEntry> in = TestData.random(40 + m.ordinal(), 10, 2000, false);
            Path f = dir.resolve(m + ".zip");
            Files.write(f, zip(in, m));
            run(dir, "unzip", "-tq", f.toString());
            Path out = dir.resolve("out-" + m);
            run(dir, "unzip", "-q", f.toString(), "-d", out.toString());
            assertEquals(Archives.snapshot(out), sortedDirsFirstView(in), "extracted by unzip " + m);
        }
    }

    /** Snapshot of the extracted tree includes implicit parents; the input only lists some, so compare after normalising. */
    private static List<ArchiveEntry> sortedDirsFirstView(List<ArchiveEntry> in) {
        java.util.TreeMap<String, ArchiveEntry> map = new java.util.TreeMap<>();
        for (ArchiveEntry e : in) {
            String[] parts = e.name().split("/");
            StringBuilder p = new StringBuilder();
            for (int i = 0; i < parts.length - 1; i++) {
                p.append(parts[i]).append('/');
                map.putIfAbsent(p.toString(), new ArchiveEntry(p.toString(), new byte[0]));
            }
            map.put(e.name(), e);
        }
        return new ArrayList<>(map.values());
    }

    @Test
    void weReadInfoZipArchives(@TempDir Path dir) throws Exception {
        assumeTrue(tool("zip", "-v"), "zip not installed");
        Path src = dir.resolve("src");
        List<ArchiveEntry> in = TestData.random(77, 10, 4000, false);
        Archives.extractTo(src, in);
        Path z = dir.resolve("t.zip");
        run(src, "zip", "-q", "-r", z.toString(), ".");
        List<ArchiveEntry> got = ZipReader.read(Files.readAllBytes(z));
        // zip(1) writes "./"-less names relative to cwd and adds directory entries for every directory
        java.util.TreeMap<String, ArchiveEntry> byName = new java.util.TreeMap<>();
        for (ArchiveEntry e : got) {
            byName.put(e.name(), e);
        }
        for (ArchiveEntry e : sortedDirsFirstView(in)) {
            assertEquals(e, byName.get(e.name()), e.name());
        }
        assertEquals(sortedDirsFirstView(in).size(), got.size());
        // and with -0 (stored) and extra fields (zip adds UT/ux extra fields by default)
        Path z0 = dir.resolve("t0.zip");
        run(src, "zip", "-q", "-0", "-r", z0.toString(), ".");
        assertEquals(got.size(), ZipReader.read(Files.readAllBytes(z0)).size());
    }

    // ---- strictness: each crafted defect has a control that differs only by that defect ----

    @Test
    void controlLoads() {
        assertEquals(THREE, ZipReader.read(zip(THREE, Method.DEFLATED)));
        assertEquals(THREE, ZipReader.read(zip(THREE, Method.STORED)));
    }

    @Test
    void crcMismatchRejected() {
        byte[] z = zip(THREE, Method.STORED);
        le(z).putInt(central(z, 0) + 16, le(z).getInt(central(z, 0) + 16) ^ 1);
        le(z).putInt(local(z, 0) + 14, le(z).getInt(local(z, 0) + 14) ^ 1); // local agrees: only the data CRC is wrong
        assertRejected(z, "crc");
    }

    @Test
    void localCentralDisagreementRejected() {
        byte[] z = zip(THREE, Method.STORED);
        le(z).putInt(local(z, 0) + 14, le(z).getInt(local(z, 0) + 14) ^ 1); // only local differs
        assertRejected(z, "local");
        byte[] z2 = zip(THREE, Method.STORED);
        le(z2).putShort(local(z2, 0) + 8, (short) 8); // method differs
        assertRejected(z2, "method");
        byte[] z3 = zip(THREE, Method.STORED);
        z3[local(z3, 0) + 30] = 'X'; // name differs
        assertRejected(z3, "name");
    }

    @Test
    void sizeMismatchRejected() {
        List<ArchiveEntry> one = List.of(TestData.file("f", "q".repeat(400)));
        byte[] z = zip(one, Method.DEFLATED);
        int c = central(z, 0);
        int declared = le(z).getInt(c + 24);
        assertEquals(400, declared);
        // stream is longer than the declared size
        byte[] shorter = z.clone();
        le(shorter).putInt(c + 24, 399);
        le(shorter).putInt(local(shorter, 0) + 22, 399);
        assertRejected(shorter, "size");
        // stream is shorter than the declared size
        byte[] longer = z.clone();
        le(longer).putInt(c + 24, 401);
        le(longer).putInt(local(longer, 0) + 22, 401);
        assertRejected(longer, "size");
        // one slack byte after the deflate stream: harmless unless the headers claim it as compressed data
        int ds = local(z, 0) + 30 + 1;
        int de = ds + le(z).getInt(c + 20);
        byte[] slack = new byte[z.length + 1];
        System.arraycopy(z, 0, slack, 0, de);
        System.arraycopy(z, de, slack, de + 1, z.length - de);
        le(slack).putInt(eocd(slack) + 16, le(z).getInt(eocd(z) + 16) + 1);
        assertEquals(one, ZipReader.read(slack), "control: unclaimed slack byte");
        le(slack).putInt(central(slack, 0) + 20, le(z).getInt(c + 20) + 1);
        le(slack).putInt(local(slack, 0) + 18, le(z).getInt(c + 20) + 1);
        assertRejected(slack, "compressed");
        assertEquals(one, ZipReader.read(z)); // control
    }

    @Test
    void sizeCapIsCheckedBeforeAllocation() {
        List<ArchiveEntry> one = List.of(new ArchiveEntry("big", new byte[5000]));
        byte[] z = zip(one, Method.DEFLATED);
        assertEquals(one, ZipReader.read(z, 5000));
        assertRejected2(z, 4999);
        // a lying header claims 4 GiB-2; reading must fail fast without allocating it
        byte[] lie = z.clone();
        le(lie).putInt(central(lie, 0) + 24, 0xFFFFFFFE);
        le(lie).putInt(local(lie, 0) + 22, 0xFFFFFFFE);
        ArchiveException ex = assertThrows(ArchiveException.class, () -> ZipReader.read(lie));
        assertTrue(ex.getMessage().contains("too large"), ex.getMessage());
    }

    private static void assertRejected2(byte[] z, long cap) {
        ArchiveException ex = assertThrows(ArchiveException.class, () -> ZipReader.read(z, cap));
        assertTrue(ex.getMessage().contains("too large"), ex.getMessage());
    }

    @Test
    void zip64AndFlagsAndMethodsRejected() {
        byte[] z = zip(THREE, Method.STORED);
        byte[] z64 = z.clone();
        le(z64).putShort(eocd(z64) + 8, (short) 0xFFFF);
        le(z64).putShort(eocd(z64) + 10, (short) 0xFFFF);
        assertRejected(z64, "zip64");
        byte[] sz = z.clone();
        le(sz).putInt(central(sz, 0) + 24, 0xFFFFFFFF);
        assertRejected(sz, "zip64");
        byte[] enc = z.clone();
        le(enc).putShort(central(enc, 0) + 8, (short) 0x0801);
        le(enc).putShort(local(enc, 0) + 6, (short) 0x0801);
        assertRejected(enc, "encrypted");
        byte[] flag = z.clone();
        le(flag).putShort(central(flag, 0) + 8, (short) 0x0810 );
        assertRejected(flag, "flag");
        byte[] meth = z.clone();
        le(meth).putShort(central(meth, 0) + 10, (short) 9);
        le(meth).putShort(local(meth, 0) + 8, (short) 9);
        assertRejected(meth, "method");
        byte[] ver = z.clone();
        le(ver).putShort(central(ver, 0) + 6, (short) 45);
        assertRejected(ver, "version");
        byte[] disk = z.clone();
        le(disk).putShort(central(disk, 0) + 34, (short) 1);
        assertRejected(disk, "disk");
        byte[] eodisk = z.clone();
        le(eodisk).putShort(eocd(eodisk) + 4, (short) 1);
        assertRejected(eodisk, "disk");
        byte[] cddisk = z.clone();
        le(cddisk).putShort(eocd(cddisk) + 6, (short) 1); // disk holding the central directory
        assertRejected(cddisk, "disk");
        byte[] storedMismatch = z.clone();
        le(storedMismatch).putInt(central(storedMismatch, 0) + 20, le(z).getInt(central(z, 0) + 20) + 1);
        assertRejected(storedMismatch, "stored");
        assertEquals(THREE, ZipReader.read(z));
    }

    @Test
    void eocdAndDirectoryStructureRejected() {
        byte[] z = zip(THREE, Method.STORED);
        int e = eocd(z);
        byte[] count = z.clone();
        le(count).putShort(e + 8, (short) 2);
        le(count).putShort(e + 10, (short) 2);
        assertRejected(count, "central");
        byte[] mismatch = z.clone();
        le(mismatch).putShort(e + 8, (short) 2);
        assertRejected(mismatch, "entries");
        byte[] moreCount = z.clone();
        le(moreCount).putShort(e + 8, (short) 4);
        le(moreCount).putShort(e + 10, (short) 4);
        assertRejected(moreCount, "central");
        byte[] gap = z.clone();
        le(gap).putInt(e + 12, le(z).getInt(e + 12) + 1); // central size one too large
        assertRejected(gap, "central");
        byte[] off = z.clone();
        le(off).putInt(e + 16, le(z).getInt(e + 16) - 1);
        assertRejected(off, "central");
        byte[] cl = z.clone();
        le(cl).putShort(e + 20, (short) 1); // comment length claims a byte that is not there
        assertRejected(cl, "end of central");
        byte[] trailing = java.util.Arrays.copyOf(z, z.length + 1);
        assertRejected(trailing, "end of central");
        byte[] withGap = new byte[z.length + 1]; // one stray byte between the directory and the EOCD
        System.arraycopy(z, 0, withGap, 0, e);
        System.arraycopy(z, e, withGap, e + 1, z.length - e);
        assertRejected(withGap, "central");
        byte[] overrun = z.clone();
        le(overrun).putShort(central(overrun, 2) + 32, (short) 1); // last header's comment runs 1 byte past the directory
        assertRejected(overrun, "central");
        byte[] sig = z.clone();
        sig[central(sig, 1)] ^= 1;
        assertRejected(sig, "central");
        assertRejected(new byte[0], "end of central");
        assertRejected(new byte[21], "end of central");
    }

    @Test
    void nameDefectsRejected() {
        byte[] z = zip(List.of(TestData.file("ab/cde", "1"), TestData.file("qq/rst", "2")), Method.STORED);
        assertEquals(2, ZipReader.read(z).size());
        assertRejected(patchName(z, 0, "../cde"), "name");
        assertRejected(patchName(z, 0, "/b/cde"), "name");
        assertRejected(patchName(z, 0, "ab\\cde"), "name");
        assertRejected(patchName(z, 0, "ab/./e"), "name");
        assertEquals("xy/cde", ZipReader.read(patchName(z, 0, "xy/cde")).get(0).name()); // control: harmless
        assertRejected(patchName(z, 1, "ab/cde"), "duplicate");
        byte[] badUtf8 = z.clone();
        badUtf8[central(badUtf8, 0) + 46] = (byte) 0xFF;
        badUtf8[local(badUtf8, 0) + 30] = (byte) 0xFF;
        assertRejected(badUtf8, "utf-8");
    }

    @Test
    void slashVariantDuplicateRejected() {
        byte[] z = zip(List.of(new ArchiveEntry("ab/", new byte[0]), TestData.file("abc", "")), Method.STORED);
        assertEquals(2, ZipReader.read(z).size());
        assertRejected(patchName(z, 1, "ab/"), "duplicate"); // "ab/" twice
    }

    /** Overwrites the name of entry k (same length) in both headers. */
    private static byte[] patchName(byte[] z, int k, String name) {
        byte[] c = z.clone();
        byte[] n = name.getBytes(StandardCharsets.UTF_8);
        int cp = central(z, k);
        int lp = local(z, k);
        assertEquals(le(z).getShort(cp + 28), n.length);
        System.arraycopy(n, 0, c, cp + 46, n.length);
        System.arraycopy(n, 0, c, lp + 30, n.length);
        return c;
    }

    @Test
    void parentFileConflictRejectedOnRead() {
        byte[] z = zip(List.of(TestData.file("abc", "1"), TestData.file("q/r/s", "2")), Method.STORED);
        assertEquals(2, ZipReader.read(z).size());
        assertRejected(patchName(z, 1, "abc/d"), "parent"); // "abc" is a file and now also a parent
    }

    @Test
    void directoryWithDataRejected() {
        List<ArchiveEntry> e = List.of(TestData.file("dd", "1234"));
        byte[] z = zip(e, Method.STORED);
        assertEquals(e, ZipReader.read(z));
        byte[] d = patchName(z, 0, "d/");
